CREATE TABLE "topics" (
	"name" text PRIMARY KEY NOT NULL,
	"slug" text NOT NULL,
	"emoji" text NOT NULL,
	"color" text NOT NULL,
	"what" text NOT NULL,
	"why" text NOT NULL,
	"first" text NOT NULL,
	"not_for" text NOT NULL,
	"tags" jsonb DEFAULT '[]'::jsonb NOT NULL,
	"enabled" boolean DEFAULT true NOT NULL,
	"origin" text DEFAULT 'team' NOT NULL,
	"position" integer DEFAULT 0 NOT NULL,
	"icon" "bytea",
	"icon_at" timestamp with time zone,
	"icon_tries" integer DEFAULT 0 NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "topics_slug_unique" UNIQUE("slug")
);
--> statement-breakpoint
-- Первые темы: те же, что в TOPIC_GUIDES ядра (packages/core/src/topics.ts), цвета — из tokens.css сайта.
INSERT INTO "topics" ("name", "slug", "emoji", "color", "what", "why", "first", "not_for", "origin", "position") VALUES
  ('баня', 'banya', '🔥', '#e0442e', 'Парная с чередованием жара и холода: заходишь погреться, выходишь остыть в купель, отдыхаешь — и так несколько кругов.', 'Сюда приходят замедлиться, согреться и побыть без телефона. После нескольких кругов многие чувствуют приятную усталость и хорошо спят.', 'Возьми купальник, полотенце и сменную одежду. В парной сидишь столько, сколько комфортно: выйти раньше других — нормально. Пей воду и не приходи на полный желудок.', 'Жар и ледяная вода — нагрузка на сердце и сосуды. При беременности, проблемах с давлением или сердцем сначала спроси врача и предупреди ведущего.', 'built_in', 1),
  ('йога', 'yoga', '🧘', '#e8891a', 'Занятие, где переходят из позы в позу в ритме дыхания. Стили разные: от медленной хатха- и инь-йоги до динамичной виньясы.', 'Приходят размять тело после сидячего дня, отдохнуть головой и держать регулярную практику в компании.', 'Удобная одежда, без еды за пару часов. Коврик часто дают на месте — уточни у организатора. Делай позы в своей амплитуде: тянуться через боль не нужно, отдохнуть можно в любой момент.', 'Смотри на стиль и уровень: динамичная виньяса и группы «для продолжающих» новичку тяжелы. При травмах спины и суставов или беременности предупреди преподавателя заранее.', 'built_in', 2),
  ('телесные практики', 'body', '🌿', '#2f9e6a', 'Занятия, где внимание направлено на ощущения в теле: медленные движения, напряжение и расслабление мышц, дыхание, иногда звук.', 'Приходят отдохнуть от головы, заметить, где копится напряжение, и научиться простым приёмам, которые можно повторять дома.', 'Удобная одежда, без плотной еды за час-два. Большую часть времени обычно лежишь или сидишь, говорить о себе не обязательно. Любое упражнение можно пропустить.', 'Это не лечение и не замена врачу или психотерапевту. При травмах и острых состояниях предупреди ведущего заранее.', 'built_in', 3),
  ('спорт', 'sport', '🏐', '#65a30d', 'Тренировки и игры в группе: пробежки, волейбол, футбол, функциональные тренировки, сёрфинг, походы.', 'Приходят подвигаться, держать форму вместе с другими и найти компанию, с которой тренироваться регулярно.', 'Спортивная одежда, обувь под формат и вода. Приди за 10 минут до начала и скажи организатору, что ты впервые: подберут темп или место в команде.', 'Нагрузка бывает высокой — смотри на уровень в анонсе. В жару пей больше воды. При проблемах с сердцем или свежих травмах сначала спроси врача.', 'built_in', 4),
  ('психологические группы', 'psy', '🫂', '#7a5af8', 'Встречи небольшой группой с ведущим, где говорят о личном: отношениях, чувствах, трудных ситуациях. Форматы разные — от терапевтической группы до расстановок.', 'Приходят, чтобы взглянуть на свою ситуацию со стороны, услышать других и не оставаться с переживаниями в одиночку.', 'Можно сначала слушать и говорить столько, сколько готов. Сказанное в группе принято не выносить наружу. Спросить ведущего об образовании и методе — нормальный вопрос.', 'Методы очень разные, и доказательная база у них разная: спроси ведущего, на что опирается его подход. В остром состоянии лучше обратиться к врачу или психотерапевту лично.', 'built_in', 5),
  ('танцы', 'dance', '💃', '#e2368f', 'Групповые занятия и мастер-классы: преподаватель показывает движения, группа повторяет под музыку. В парных танцах партнёры меняются.', 'Приходят подвигаться, познакомиться с людьми и выучить то, что потом можно танцевать на вечеринках.', 'Пара обычно не нужна — её находят на месте. Удобная одежда и обувь, которая не скользит; вода с собой. Ошибаться на первом занятии — норма.', 'Смотри на уровень группы: в «продолжающих» новичку будет тяжело успевать.', 'built_in', 6),
  ('творчество', 'art', '🎨', '#e0a000', 'Мастер-классы и кружки, где делают что-то руками: рисуют, собирают коллажи, составляют букеты. Ведущий показывает приём, дальше каждый делает своё.', 'Приходят переключиться с экрана на руки, провести пару часов в спокойной компании и унести домой готовую вещь.', 'Уметь рисовать или «делать красиво» не нужно. Материалы обычно входят в стоимость — уточни это у организатора. Одежду выбирай ту, которую не жалко испачкать.', 'Мест, как правило, мало, и материалы закупают заранее: запишись заблаговременно и предупреди, если не придёшь.', 'built_in', 7),
  ('кино', 'cinema', '🎬', '#2f55d4', 'Совместный просмотр фильма: киноклуб, показ под открытым небом или вечер с разбором после титров.', 'Приходят посмотреть то, до чего не доходят руки в одиночку, и поговорить о фильме с людьми.', 'В обсуждении можно просто слушать — говорить никто не заставляет. Приди за 10–15 минут до начала: места часто не закреплены.', 'Проверь язык фильма и субтитров и сколько длится встреча вместе с обсуждением.', 'built_in', 8),
  ('обучение', 'learn', '🎓', '#4f46e5', 'Лекции, тренинги, разговорные и языковые клубы, мастермайнды: встречи, на которые идут за знанием или навыком.', 'Приходят разобраться в теме, попрактиковать язык или навык вживую и получить ответ на свой вопрос от ведущего.', 'Посмотри, на какой уровень рассчитана встреча. На лекции можно просто слушать; на тренинге и в разговорном клубе придётся участвовать — ошибаться там нормально.', 'Проверь язык встречи и уровень: группа «для продолжающих» новичку будет тяжела. Спросить ведущего об опыте и программе — нормальный вопрос.', 'built_in', 9),
  ('детям', 'kids', '🧒', '#f0653a', 'Занятия для детей: научные опыты, мастер-классы, творческие и игровые встречи. Ведущий работает с группой, взрослые ждут рядом или участвуют вместе с ребёнком.', 'Приводят детей, чтобы они попробовали новое руками, пообщались со сверстниками и провели время не за экраном.', 'Посмотри возраст в анонсе и уточни, остаётся ли взрослый на занятии. Одежду выбирай ту, которую не жалко испачкать; вода с собой.', 'Занятия рассчитаны на свой возраст: младшим будет сложно, старшим скучно. Про аллергии и особенности ребёнка предупреди ведущего заранее.', 'built_in', 10),
  ('игры', 'games', '🎲', '#0f8fd6', 'Вечера настольных игр, шахматы, квизы, мафия — игры, где играют компанией или командами.', 'Приходят азартно провести вечер, подумать головой и познакомиться с людьми через игру, а не через разговор о погоде.', 'Правила обычно объясняют на месте. Прийти одному — нормально: в команду поставят. На квиз можно и своей командой — уточни, сколько в ней может быть человек.', 'Смотри на уровень: шахматный клуб «для продолжающих» или турнир — не место для первого знакомства с игрой. Еду и напитки в кафе обычно оплачиваешь отдельно.', 'built_in', 11),
  ('встречи и общение', 'meet', '☕', '#0e9f95', 'Неформальные встречи за едой, музыкой или общей темой: завтраки, бранчи, вечеринки, свопы. Программы почти нет — главное здесь люди.', 'Приходят познакомиться с людьми в городе и провести время не в одиночку.', 'Прийти одному — нормально, многие так и делают. Обычно ведущий сам знакомит участников. Еду и напитки чаще всего оплачиваешь отдельно.', 'Если встреча заявлена на тему (профессия, метод ведущего), разговор пойдёт о ней — убедись, что тема тебе интересна.', 'built_in', 12);
